import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Fragment,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";

import { arrowRight, calendarBlank } from "../../../icons";
import { generateShortID } from "../../utils/function-helper";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import browserLanguage from "../../utils/i18n/browserLang";
import { hasSlot } from "../../utils/slot";
import { Aria } from "../calendar/types";

import {
	formatInput,
	getDateFormat,
	getEnFormat,
	initConfig,
	isEmpty,
	isValidDate,
	parseToEnUsFormat,
	setDateInFormat,
	swapDateFormat,
	validUserInput,
	valueValidDate,
} from "./util";

import type { CalendarConfig } from "../calendar/types";

let id = 0;

type TimePanelConfig = {
	hours?: string[];
	minutes?: string[];
	seconds?: string[];
	hour?: string;
	minute?: string;
	second?: string;
	i18n?: {
		hour: string;
		min: string;
		sec: string;
		ok: string;
	};
	showSeconds?: boolean;
	disabled?: boolean;
};

/**
 * @since 0.1.49
 * @status stable
 *
 * @slot label - The date picker label.
 * @slot label-suffix - The label suffix content.
 * @slot help-text - The help text content.
 * @slot start-label - The start date label.
 * @slot end-label - The end date label.
 * @slot calendar - The calendar.
 * @slot time - The time picker panel.
 * @slot clear-icon - The clear icon.
 * @slot suffix - The suffix content.
 * @slot suffix-end - The suffix content for the end date.
 * @slot panel-footer - The panel footer content.
 *
 * @part label - The label element.
 * @part asterisk - The asterisk element.
 * @part base - The component's base wrapper.
 * @part element - The input element.
 * @part input - The input element.
 * @part prefix - The prefix part.
 * @part suffix - The suffix part.
 * @part range - The range picker's base wrapper.
 * @part panel - The dropdown panel.
 * @part help-text - The help text element.
 * @part base-end - The end date picker's base wrapper.
 * @part input-end - The end date input.
 * @part label-end - The end date label.
 * @part prefix-end - The prefix content for the end date.
 * @part clear-button-end - The clear button for the end date.
 * @part suffix-end - The suffix content for the end date.
 * @part time-picker-label - The time picker label.
 * @part time-picker-base - The time picker base wrapper.
 * @part time-picker-input-base - The time picker input base wrapper.
 * @part time-picker-prefix - The time picker prefix content.
 * @part time-picker-suffix - The time picker suffix content.
 * @part dropdown - The dropdown.
 * @part dropdown-panel - The dropdown panel.
 * @part input-base - The input base wrapper.
 * @part calendar-base - The calendar base wrapper.
 * @part calendar - The calendar.
 * @part header - The calendar header.
 * @part month-year - The calendar month and year.
 * @part week-title - The calendar week title.
 * @part week - The calendar week.
 * @part day - The calendar day.
 */

@Component({
	tag: "hbr-date-picker",
	styleUrl: "date-picker.scss",
	shadow: true,
})
export class DatePicker {
	@Element() host: HTMLHbrDatePickerElement;

	@State() hasFocus = false;
	@State() hasContent = false;
	@State() hasHelpTextSlot = false;
	@State() hasLabelSlot = false;
	@State() hasStartLabelSlot = false;
	@State() hasEndLabelSlot = false;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;
	@State() panelOpen = false;
	@State() uuid = generateShortID();
	@State() dateString: string | string[] = "";
	@State() config: CalendarConfig = {};
	@State() calendarView = "day";

	/** The calendar open state. */
	@Prop({ reflect: true, mutable: true }) open = false;

	/** Name */
	@Prop({ reflect: true }) name: string;

	/** Calendar UI hoist option, refer the select doc */
	@Prop({ reflect: true }) hoist: boolean;

	/** The range picker styles. */
	@Prop({ reflect: true }) variant: string;

	/** Calendar trigger */
	@Prop({ reflect: true }) trigger = "input";

	/** Value */
	@Prop({ mutable: true }) value: string | string[] = "";

	/** Single label */
	@Prop({ reflect: true }) label = "";
	/** Labels. Use the following key value pairs: {startDate: DATE, endDate: DATE} */
	@Prop({ reflect: true }) labels;

	/** Single placeholder */
	@Prop({ reflect: true }) placeholder: string;

	/** Placeholders for range picker. Use the following key value pairs: {startDate: DATE, endDate: DATE} */
	@Prop({ reflect: true }) placeholders;

	/** Date format like mm/dd/yyyy. If locale is set, no need to pass this. */
	@Prop({ mutable: true }) format: string;

	/** The minimum/earliest date that can be selected. */
	@Prop({ reflect: true, mutable: true }) minDate: string | Date;

	/** The maximum/lates date that can be selected. */
	@Prop({ reflect: true, mutable: true }) maxDate: string | Date;

	/** Help text for single */
	@Prop({ reflect: true, mutable: true }) helpText: string;

	/** Help text id */
	@Prop({ reflect: true }) helpTextId = "";

	/** Set to true to disable the date-picker. */
	@Prop({ reflect: true, mutable: true }) disabled = false;

	/** Required  */
	@Prop({ reflect: true }) required = false;

	/** Set to true to make the date-picker to error state. */
	@Prop({ reflect: true, mutable: true }) error: boolean | boolean[];

	/* Size */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/* Range Picker */
	@Prop({ reflect: true }) range = false;

	/* Date Picker with Time */
	@Prop({ reflect: true }) time = false;

	/* Date Picker with Time picker panel  */
	@Prop({ reflect: true }) timePanel = false;

	/* Width */
	@Prop({ reflect: true }) width: string;

	/** Specify default date formatting for language (locale). */
	@Prop({ mutable: true, reflect: true }) locale: string;

	/**  language defaults for month and weekday names (see internationalization below) */
	@Prop({ mutable: true }) i18n;

	/** Attributes related to screen readers. */
	@Prop() aria: {
		calendarLabel?: string;
		rangeCalendarLabel?: string;
		calendarLevel?: number;
		calendarRole?: string;
		calendarModal?: boolean;
		prevYear?: string;
		nextYear?: string;
		prevMonth?: string;
		nextMonth?: string;
		inputLabel: string;
	};

	/** First day of the week (0: Sunday, 1: Monday, etc) */
	@Prop({ mutable: true }) firstDay: number;

	/** Render the month after year in the title on the calendar. */
	@Prop() showMonthAfterYear: boolean;

	/** Used with numberOfMonths. To choose which side the main calendar will be. */
	@Prop() mainCalendar: string;

	/** Render days of the calendar grid that fall in the next or previous months. */
	@Prop() showDaysInNextAndPreviousMonths: boolean;

	/** The number of years to display. */
	@Prop() yearRange: number | Array<number> = 10;

	/**
	 * This will be true when the control is in an invalid state. Validity in range inputs is determined by the message
	 * provided by the `setCustomValidity` method.
	 */
	@Prop({ mutable: true, reflect: true }) invalid = false;

	@Prop() calendarStyle: string;

	/** Aria label for the input if no label in present.  Deprecate candidate. Use "aria={inputLabel: value}" instead. */
	@Prop() ariaInput: string;

	/** Aria label for the calendar icon. Deprecate candidate. Use "aria={calendarLabel: value}" instead. */
	@Prop() ariaCalendar: string;

	/** Time picker configuration. */
	@Prop({ mutable: true }) timeConfig: TimePanelConfig;

	/** External anchor reference. Use <hbr-input> only. */
	@Prop() anchor: string | HTMLHbrInputElement | HTMLElement;

	/**
	 * The preferred placement of the dropdown panel. Note that the actual placement may vary as needed to keep the panel
	 * inside of the viewport.
	 */
	@Prop({ reflect: true }) placement:
		| "top"
		| "top-start"
		| "top-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "right"
		| "right-start"
		| "right-end"
		| "left"
		| "left-start"
		| "left-end" = "bottom-start";

	inputId = `date-picker-${++id}`;
	labelId = `date-picker-label-${id}`;
	_helpTextId = `date-picker-helpTextId-${id}`;
	datePicker: HTMLElement;
	private calendar: HTMLHbrCalendarElement;
	private cleared: boolean; //emit change event when cleared
	input: HTMLHbrInputElement;
	inputStart: HTMLHbrInputElement;
	inputEnd: HTMLHbrInputElement;
	dropdown: HTMLHbrDropdownElement;
	timePicker: HTMLHbrTimePickerElement;
	timePickerEnd: HTMLHbrTimePickerElement;
	private anchorRef: HTMLHbrInputElement;
	private timePanelRef: HTMLHbrTimePanelElement;
	private calendarIconRef: HTMLHbrIconButtonElement;
	private _locale: string;
	private defaultAria: Aria = {
		role: "dialog",
		label: "Choose Date",
		modal: true,
		level: 3,
		prevYear: "Previous Year",
		nextYear: "Next Year",
		prevMonth: "Previous Month",
		nextMonth: "Next Month",
	};
	private calendarDaySelected: boolean;
	private setLocaleByLanguage: boolean;

	isValid = true;
	onValidating: boolean;
	calendarTrigger: boolean;
	labelExist: boolean;
	placeholdersExist: boolean;
	helpTextsExist: boolean;
	errorExist: boolean;
	outlined: boolean;
	focusedInput: string;
	magnetic: boolean;
	id: string;
	onSelectFromCalendar: boolean;
	customFormat: boolean;
	hasHelpText: boolean;

	// private calendarView = "day";

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	@Watch("disabled")
	handleDisabledChange() {
		if (this.range) {
			if (this.inputStart) {
				this.inputStart.disabled = this.disabled;
				this.inputEnd.disabled = this.disabled;
			}
		} else {
			if (this.input) this.input.disabled = this.disabled;
			// (this.input as HTMLHbrInputElement).disabled = this.disabled;
		}
	}

	@Watch("minDate")
	handleMinDateChange() {
		const min = setDateInFormat(this.minDate);
		(async () => {
			await this.calendar?.setMinDate(min);
		})();
	}

	@Watch("maxDate")
	handleMaxDateChange() {
		const max = setDateInFormat(this.maxDate);
		(async () => {
			await this.calendar?.setMaxDate(max);
		})();
	}

	@Watch("value")
	handleValueChange() {
		const { calendar, value, error } = this;
		/** if value is set systematically we need to update the calendar UI */
		if (error) {
			return;
		}
		if (!this.onSelectFromCalendar) {
			if (this.range) {
				calendar?.clear();
				const startDate = value[0];
				const endDate = value[1];
				startDate
					? calendar.setStartRange(this.newDateFn(new Date(startDate)))
					: calendar.setStartRange(null);
				if (endDate) {
					calendar.setEndRange(this.newDateFn(new Date(endDate)));
				} else {
					calendar.setEndRange(null);
				}
				calendar.draw();
			} else {
				if (value && !Array.isArray(value)) {
					calendar?.setDate(new Date(value));
				} else {
					calendar?.clear();
				}
			}
		}
	}

	@Watch("error")
	handleErrorChange() {
		if (this.error) {
			this.isValid = false;
		}
	}

	@Watch("anchor")
	handleAnchorChange() {
		/** we only accept <hbr-input> as an anchor.  */
		if (!this.anchor) {
			return;
		}
		if (this.anchorRef && this.anchorRef instanceof HTMLHbrInputElement) {
			return;
		}
		if (typeof this.anchor === "string") {
			this.anchorRef = document.querySelector(this.anchor);
		} else if (this.anchor instanceof HTMLHbrInputElement) {
			this.anchorRef = this.anchor;
		}

		this.input = this.anchorRef;
		this.bindEventsToAnchor();
	}

	@Watch("locale")
	handleLocaleChange(cur: string, prev: string) {
		this.setLocaleByLanguage = cur && !prev ? true : false;
		if (!this._locale) {
			if (!this.setLocaleByLanguage) {
				this._locale = this.locale;
			}
		}
	}

	/** Emitted when the input loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	/** Emitted when the changes. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter<{
		isValid: boolean;
		value: string | string[];
		focused?: string;
		date?: Date | Date[];
		utc?: string | string[];
	}>;

	/** Emitted when the control gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	/** Emitted when the calendar title is focused. */
	@Event({ eventName: "hbr-calendar-title-keydown" })
	hbrCalendarTitleKeydown: EventEmitter;

	/** Simulates a click on the input. */
	@Method()
	async setClick() {
		if (this.range) {
			this.inputStart.click();
		} else {
			this.input.click();
		}
	}

	/** Sets focus on the input. */
	@Method()
	async setFocus(input) {
		this.host.shadowRoot?.querySelector(input)?.focus();
		return setTimeout(() =>
			this.host.shadowRoot
				?.querySelector(input)
				?.setSelectionRange(0, 0, "none"),
		);
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	@Method()
	async reportValidity() {
		if (this.range) {
			return this.inputStart.reportValidity() && this.inputEnd.reportValidity();
		}
		return this.input.reportValidity();
	}

	/** Sets a custom validation message. If `message` is not empty, the field will be considered invalid. */
	@Method()
	async setCustomValidity(message: string) {
		if (this.range) {
			this.inputStart.setCustomValidity(message);
			this.inputEnd.setCustomValidity(message);
		} else {
			this.input.setCustomValidity(message);
		}
	}

	private bindEventsToAnchor() {
		this.anchorRef.addEventListener("blur", this.handleFocusout);
		this.anchorRef.addEventListener("focus", this.handleFocus);
		this.anchorRef.addEventListener("change", this.handleHbrChange);
		this.anchorRef.addEventListener("keyup", this.handleKeyup);
		this.anchorRef.addEventListener("keydown", this.handleKeydown);
		this.anchorRef.addEventListener("input", this.handleInput);
		this.anchorRef.addEventListener("click", this.handleClick);
	}
	private removeEventsToAnchor() {
		this.anchorRef.removeEventListener("blur", this.handleFocusout);
		this.anchorRef.removeEventListener("focus", this.handleFocus);
		this.anchorRef.removeEventListener("change", this.handleHbrChange);
		this.anchorRef.removeEventListener("keyup", this.handleKeyup);
		this.anchorRef.removeEventListener("keydown", this.handleKeydown);
		this.anchorRef.removeEventListener("input", this.handleInput);
		this.anchorRef.removeEventListener("click", this.handleClick);
	}

	connectedCallback() {
		this.handleFocus = this.handleFocus.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleHbrChange = this.handleHbrChange.bind(this);
		this.handleInputStartChange = this.handleInputStartChange.bind(this);
		this.handleInputEndChange = this.handleInputEndChange.bind(this);
		this.handleKeyup = this.handleKeyup.bind(this);
		this.handleKeydown = this.handleKeydown.bind(this);
		this.handleClick = this.handleClick.bind(this);
		this.handleOKButtonClick = this.handleOKButtonClick.bind(this);
		this.handleOKButtonKeydown = this.handleOKButtonKeydown.bind(this);
		this.handleCalendarKeydown = this.handleCalendarKeydown.bind(this);
		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}

	componentWillLoad() {
		this.handleSlotChange();
		if (this.trigger === "calendar") this.calendarTrigger = true;

		/** get localization setup */
		if (this.locale) {
			this._locale = this.locale;
		}
		if (!this.locale) {
			const language = browserLanguage();
			this.setLocaleByLanguage = true;
			this.locale = language;
		}
		const { format, range, value } = this;
		if (format && format !== "mm/dd/yyyy") {
			this.customFormat = true; //make sure it's not a default format
			this.placeholder = format;
			if (this.anchorRef && !this.anchorRef.placeholder) {
				this.input.placeholder = format;
			}
		} else if (this.locale !== "en") {
			getDateFormat(this);
		} else {
			getEnFormat(this);
		}

		if (range) {
			this.outlined = this.variant && this.variant === "outline";
			if (!this.dateString) {
				//initialize
				if (value?.length) {
					if (isValidDate(value[0], this) && isValidDate(value[1], this)) {
						this.dateString = [
							new Date(value[0]).toISOString(),
							new Date(value[1]).toISOString(),
						];
					} else {
						this.dateString = ["", ""];
					}
				} else {
					this.dateString = ["", ""];
				}
			}
			if (!this.outlined) {
				this.labelExist =
					this.labels &&
					Array.isArray(this.labels) &&
					this.labels.length &&
					this.labels.some((item) => item !== "");
				this.errorExist = this.error && !!Object.keys(this.error).length;
			} else {
				this.labelExist = !!this.label;
			}
			this.placeholdersExist =
				this.placeholder && !!Object.keys(this.placeholder).length;
		} else {
			this.labelExist = !!this.label;
			if (value && !this.dateString && isValidDate(value, this)) {
				this.dateString =
					typeof value === "string" && new Date(value).toISOString();
			}
		}
		this.hasHelpText = this.helpText ? true : this.hasHelpTextSlot;
		this.config = initConfig(this);

		if (this.calendarStyle && this.calendarStyle === "square") {
			this.magnetic = true;
		}
		this.handleAnchorChange();
	}

	disconnectedCallback() {
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
		if (this.anchorRef) {
			this.removeEventsToAnchor();
		}
	}

	componentDidRender() {
		const focusedInput: HTMLHbrInputElement = this.datePicker.querySelector(
			"[data-focused='true']",
		);
		if (focusedInput) {
			const { name } = focusedInput;
			const lastIndex = name?.lastIndexOf("-");
			this.focusedInput = lastIndex && name.slice(lastIndex + 1);
		}
	}
	componentDidUpdate() {
		/** reset */
		this.isValid = false;
		this.onSelectFromCalendar = false;
	}
	componentDidLoad() {
		if (this.value && (!this.dateString || !this.dateString.length)) {
			if (this.range && this.value.length) {
				const startDate = this.value[0];
				const endDate = this.value[1];
				if (isValidDate(startDate, this) && isValidDate(endDate, this)) {
					this.dateString = [
						new Date(this.value[0]).toISOString(),
						new Date(this.value[1]).toISOString(),
					];
				}
			}
		}
	}

	private handleFocus(event) {
		const { target } = event;
		if (target.tagName === "HBR-INPUT") {
			setTimeout(() => target.setFocus());
		}
		this.hasFocus = true;
		this.hbrFocus.emit();
	}

	private handleFocusout = (event) => {
		const { range } = this;
		const { target } = event;
		this.error = false;
		if (!range) {
			this.hbrBlur.emit();
		}
		this.hasFocus = false;
		if (!this.onSelectFromCalendar) {
			const { value } = target;
			let _value = target.value;

			let parsedEnDate: Date | string;
			if (value) {
				if (this._locale && !this._locale.includes("en")) {
					/** Usage: parseToEnUsFormat("2025/4/18", "ja-JP")
					 * converts a date from the "ja-JP" format ("2025/4/18") to the "en-US" format ("4/18/2025")
					 * for validUserInput validation. */
					parsedEnDate = parseToEnUsFormat(value, this._locale);

					if (parsedEnDate && this.dateString) {
						if (this.dateString === parsedEnDate) {
							return;
						}
					}
				} else if (
					!this._locale &&
					this.locale &&
					!this.locale.includes("en") &&
					!value.includes("/")
				) {
					//set by the browserLanguage()
					const updated = swapDateFormat(value);
					parsedEnDate = parseToEnUsFormat(updated, this.locale);
				}

				_value = !valueValidDate(parsedEnDate || value)
					? new Date(parsedEnDate || value)
					: parsedEnDate || value;

				if (!valueValidDate(_value) || !validUserInput(parsedEnDate || value)) {
					this.hbrChange.emit({
						isValid: false,
						value: value,
						focused: this.focusedInput,
					});
					this.error = true;
					return;
				}
			} else {
				if (this.cleared) {
					this.hbrChange.emit({
						isValid: this.error ? false : true,
						value: value,
						focused: this.focusedInput,
					});
					this.cleared = undefined;
				}
			}
			if (!range) {
				return;
			}

			/** check if value has changed to avoid unnecessary re-rendering */
			const rangeStart = range && target.classList.contains("hbr-range-start");
			const valueChanged = this.valueChanged(_value, rangeStart);
			const dateNotFormatted =
				_value.includes("/") || _value.includes("-") || _value.includes(".");
			const noChange = !valueChanged && !dateNotFormatted; //should update to natural language if value is same but format change only
			if (noChange) {
				return;
			}

			this.handleValidation(event);
		}
	};

	private handleClick(event) {
		const { target, key } = event;
		if (this.range) {
			if (this.dropdown.open) {
				this.open = true;
				// event.stopPropagation(); //Do not close
				event.stopPropagation();
				event.preventDefault();
			} else {
				this.open = false;
			}

			if (key === "Enter" && target.classList.contains("calendar-icon")) {
				setTimeout(() => {
					if (this.calendar) {
						let focusDay: HTMLElement;
						focusDay = this.calendar.shadowRoot.querySelector(
							".is-selected > button",
						);
						if (this.range) {
							if (!focusDay) {
								focusDay =
									this.calendar.shadowRoot.querySelector(
										".is-startrange > button",
									) ||
									this.calendar.shadowRoot.querySelector(
										".is-endrange > button",
									);
							}
						}
						if (!focusDay) {
							focusDay =
								this.calendar.shadowRoot.querySelector(".is-today > button") ||
								this.calendar.shadowRoot.querySelector("[tabindex=0]");
						}
						if (focusDay) {
							focusDay.focus();
						}
					}
				});
			}
		} else {
			if (this.trigger === "calendar") {
				if (!target.classList.contains("calendar-icon")) {
					event.stopPropagation();
				}
			}
		}
	}

	private handleInput = (event) => {
		event.stopPropagation();
	};

	private handleDateChange = (event: CustomEvent) => {
		/** Maybe we should not set value until ok button is clicked if timePanel is set to true */
		const {
			date,
			event: { key },
		} = event.detail;
		if (this.range) {
			const { startRange, endRange } = this.config;
			const startRangeUpdated =
				!this.focusedInput || this.focusedInput === "start";
			const time = date.getTime();

			/** updates */
			const updateStartRange = () => {
				if (this._locale) {
					this.inputStart.value = Intl.DateTimeFormat(this._locale).format(
						date,
					);
				} else {
					this.inputStart.value = formatInput(date.toDateString(), this);
				}

				if (typeof this.dateString === "object") {
					this.dateString = [date.toISOString(), this.dateString[1]];
				}
				this.config = { ...this.config, startRange: date };
				this.calendar.setStartRange(date);
			};
			const updateEndRange = () => {
				if (this._locale) {
					this.inputEnd.value = Intl.DateTimeFormat(this._locale).format(date);
				} else {
					this.inputEnd.value = formatInput(date.toDateString(), this);
				}

				if (typeof this.dateString === "object") {
					this.dateString = [this.dateString[0], date.toISOString()];
				}

				this.config = { ...this.config, endRange: date };
				this.calendar.setEndRange(date);
			};
			/****************************************************************/

			if (
				startRange &&
				endRange &&
				(time === startRange.getTime() || time === endRange.getTime())
			) {
				return;
			}
			if (startRangeUpdated) {
				if (endRange && time > endRange.getTime()) {
					updateEndRange();
					this.inputEnd.setFocus();
				} else {
					updateStartRange();
					this.inputEnd.setFocus();
				}
			} else {
				if (startRange && time < startRange.getTime()) {
					updateStartRange();
					this.inputEnd.setFocus();
				} else {
					updateEndRange();
					this.inputEnd.setFocus();
				}
			}
			this.calendar.setDate(date);
		} else {
			if (!this.timePanel) {
				if (this._locale) {
					this.input.value = Intl.DateTimeFormat(this._locale).format(date);
				} else {
					this.input.value = formatInput(date.toDateString(), this);
				}
				if (!this.onSelectFromCalendar) {
					this.dropdown.hide();
					this.open = false;
				}
			}
			this.dateString = date.toISOString();
			this.calendar.setDate(date);
			if (key) {
				this.input?.setFocus();
			}
			//calendar closes when date is selected in single calendar
			this.open = false;
		}
	};

	private focusMenuItemKeyboard(menu: HTMLHbrMenuElement) {
		if (!menu) return;
		const checked: HTMLHbrMenuItemElement = menu.querySelector(
			"hbr-menu-item[checked]",
		);
		if (checked) {
			checked.setFocus();
		} else {
			const menuItem: HTMLHbrMenuItemElement =
				menu.querySelector("hbr-menu-item");
			menuItem.setFocus();
		}
	}

	private handleDayKeydown = (event: CustomEvent) => {
		const { key } = event.detail;
		if (key === "Escape") {
			event.stopPropagation();
			event.preventDefault();
			setTimeout(() => {
				this.open = false;
				this.calendarIconRef?.setFocus();
			}, 100);
			return;
		}
		if (key === "tab") {
			if (this.timePanelRef) {
				event.stopPropagation();
				event.preventDefault();
				const menu: HTMLHbrMenuElement =
					this.timePanelRef.shadowRoot.querySelector("hbr-menu");
				this.focusMenuItemKeyboard(menu);
			}
		}
	};

	private handleCalendarTitleKeydown = (event: CustomEvent) => {
		const { key, target, nextElementSibling } = event.detail;
		if (this.timePanel) {
			if (key === "shift" && target === "prevYear" && nextElementSibling) {
				const panel = (event.target as HTMLElement).closest(
					".date-picker__panel",
				);
				const okButton: HTMLHbrButtonElement = panel?.querySelector(
					"slot[name='panel-footer'] hbr-button",
				);
				if (okButton) {
					if (okButton.disabled) {
						const activeItems =
							this.timePanelRef?.shadowRoot?.querySelectorAll("[tabindex='0']");
						if (activeItems?.length) {
							const activeItemArray = Array.from(activeItems);
							const activeItem = activeItemArray[activeItemArray.length - 1];
							(activeItem as HTMLHbrMenuItemElement).setFocus();
						} else {
							const activeDayButton: HTMLHbrButtonElement =
								this.calendar.shadowRoot.querySelector("[tabindex='0']");
							activeDayButton?.setFocus();
						}
					} else {
						okButton.setFocus();
					}
				} else {
					this.hbrCalendarTitleKeydown.emit({
						event,
						key: "shift",
						target: "prevYear",
						nextElementSibling,
					});
				}
			}
		} else {
			this.hbrCalendarTitleKeydown.emit({
				event,
				key: "shift",
				target: "prevYear",
				nextElementSibling,
			});
		}
	};

	private handleHbrChange = (event: CustomEvent) => {
		event.stopPropagation();

		const target = event.target as HTMLInputElement;
		const { value } = target;
		if (value && !valueValidDate(value)) {
			this.isValid = false;
			return;
		}
		this.isValid = true;
		this.error = false;
		if (this.input.value) {
			this.dateString = new Date(this.input.value).toISOString();
			this.calendar.setDate(new Date(this.input.value));
		} else {
			this.dateString = "";
			this.calendar.clear();
			this.cleared = true;
		}
	};
	private handleInputStartChange = (event: CustomEvent) => {
		event.stopPropagation();
		const target = event.target as HTMLInputElement;
		this.inputStart.value = target.value;
		if (typeof this.dateString === "object") {
			const valid = valueValidDate(this.inputStart.value);
			if (!valid) {
				this.error = true;
				return;
			}

			/** update calendar when start date got updated by user input */
			if (this.inputStart.value) {
				this.calendar.setStartRange(new Date(this.inputStart.value));
			} else {
				this.calendar.setStartRange(null);
			}
			this.dateString[0] = new Date(this.inputStart.value).toISOString();
		}
	};
	private handleInputEndChange = (event) => {
		event.stopPropagation();
		const target = event.target as HTMLInputElement;
		this.inputEnd.value = target.value;
		if (typeof this.dateString === "object") {
			const valid = valueValidDate(this.inputEnd.value);
			if (!valid) {
				this.error = true;
				return;
			}

			/** update calendar when end date got updated by user input */
			if (this.inputEnd.value) {
				this.calendar.setEndRange(new Date(this.inputEnd.value));
			} else {
				this.calendar.setEndRange(null);
			}
			this.dateString[1] = new Date(this.inputEnd.value).toISOString();
		}
	};

	private handleKeyup = (event) => {
		const { key, target } = event;
		if (key === "Enter") {
			if (target?.classList?.contains("calendar-icon")) {
				this.handleClick(event);
			} else {
				if (this.range && !target.value) {
					this.dropdown.open = true;
					setTimeout(() => {
						let focusDay: HTMLElement;

						if (this.calendar) {
							const activeDay: HTMLElement =
								this.calendar.shadowRoot.querySelector(".is-selected > button");
							if (activeDay) {
								focusDay = activeDay;
							} else {
								const today: HTMLElement =
									this.calendar.shadowRoot.querySelector(".is-today > button");
								if (today) {
									focusDay = today;
								}
							}
							if (focusDay) {
								focusDay.focus();
							} else {
								const firstActive: HTMLElement =
									this.calendar.shadowRoot.querySelector("[tabindex='0']");
								if (firstActive) {
									firstActive.focus();
								}
							}
						}
					});
				}
				this.handleValidation(event);
			}
		} else if (key === "Escape") {
			event.stopPropagation();
			event.preventDefault();
			setTimeout(() => {
				this.open = false;
				this.dropdown.open = false;
			}, 100);
			return;
		}
	};

	private handleKeydown = (event) => {
		event.stopPropagation();
	};

	private handleSlotChange() {
		this.hasContent = hasSlot(this.host);
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasLabelSlot = hasSlot(this.host, "label");
		this.hasStartLabelSlot = hasSlot(this.host, "start-label");
		this.hasEndLabelSlot = hasSlot(this.host, "end-label");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");
	}

	private handleOKButtonClick(event) {
		event.preventDefault();
		event.stopPropagation();
		const date = new Date(this.dateString.toString());
		const { hour, minute, second, showSeconds } = this.timeConfig || {};
		date.setHours(
			Number.parseInt(hour) || 0,
			Number.parseInt(minute) || 0,
			Number.parseInt(second) || 0,
			0,
		);
		if (!hour) {
			this.timeConfig = { ...this.timeConfig, hour: "00" };
		}
		if (!minute) {
			this.timeConfig = { ...this.timeConfig, minute: "00" };
		}
		if (showSeconds && !second) {
			this.timeConfig = { ...this.timeConfig, second: "00" };
		}
		this.dateString = date.toISOString();
		if (this._locale) {
			this.input.value = Intl.DateTimeFormat(this._locale).format(date);
		} else {
			this.input.value = formatInput(date.toDateString(), this);
		}
		this.value = this.dateString;
		this.hbrChange.emit({
			isValid: this.isValid,
			value: this.dateString,
			focused: this.focusedInput,
			date,
			utc: date.toUTCString(),
		});
		this.dropdown.hide();
		this.open = false;
	}

	private handleOKButtonKeydown(event) {
		const { key, shiftKey } = event;
		if (key === "Tab") {
			event.preventDefault();
			event.stopPropagation();
			if (shiftKey) {
				const panelBody =
					this.timePanelRef.shadowRoot.querySelector(".time-panel__body");
				let lastMenuColumn: HTMLElement;
				if (panelBody) {
					if (panelBody.childElementCount > 0) {
						lastMenuColumn = panelBody.lastElementChild as HTMLDivElement;
					}
				}
				const lastMenu: HTMLHbrMenuElement =
					lastMenuColumn?.querySelector("hbr-menu");
				if (lastMenu) {
					this.focusMenuItemKeyboard(lastMenu);
				}
			} else {
				const prevYearIcon: HTMLHbrIconButtonElement =
					this.calendar.shadowRoot.querySelector("[data-testid='prevYear']");
				prevYearIcon?.setFocus();
			}
		} else if (key === "Enter" || key === " ") {
			setTimeout(() => this.calendarIconRef?.setFocus(), 100);
		}
	}

	private handleCalendarKeydown(event) {
		const { key } = event;
		if (key === "Enter" || key === " ") {
			event.stopPropagation();
			event.preventDefault();
			this.open = !this.open;
			this.setFocusDay();
		}
	}

	private setFocusDay() {
		setTimeout(() => {
			let focusedDay: HTMLElement;
			const calendarTable =
				this.calendar.shadowRoot.querySelector(".calendar__content");
			if (calendarTable) {
				focusedDay = calendarTable.querySelector(".day-button-selected");
				this.calendar.getConfig().then((config) => {
					if (config.date) {
						const { date } = config;
						focusedDay = this.calendar.shadowRoot.querySelector(
							`[data-pika-year='${date.getFullYear()}'][data-pika-month='${date.getMonth()}'][data-pika-day='${date.getDate()}']`,
						);
					}
					if (!focusedDay) {
						focusedDay =
							calendarTable.querySelector(".is-today > button") ||
							this.calendar.shadowRoot.querySelector("[tabindex='0']");
					}
					if (focusedDay) {
						(focusedDay as HTMLElement).focus();
					}
				});
			}
		}, 600);
	}

	private setInputValue = (value) => {
		if (!this.range) {
			this.input.value = value;
		} else {
			this.inputStart.value = value[0];
			this.inputEnd.value = value[1];
		}
	};
	private setTimeValue = (value) => {
		if (!this.range) {
			this.timePicker.value = value;
		} else {
			this.timePicker.value = value[0];
			this.timePickerEnd.value = value[1];
		}
	};

	restructureValue(target, timeStart, rangeStart) {
		const { range, time } = this;
		const isInput = (obj) => obj?.tagName === "HBR-INPUT";
		const isTimeInput = (obj) => obj?.tagName === "HBR-TIME-PICKER";
		let value: string | string[];

		if (this.dateString) {
			return this.dateString;
		}

		if (!range) {
			if (time) {
				value = isTimeInput(target) ? target.value : this.timePicker.value;
			} else {
				value = isInput(target) ? target.value : this.input.value;
			}
		} else {
			if (time) {
				if (isTimeInput(target)) {
					value = timeStart
						? [target.value, this.timePickerEnd.value]
						: [this.timePicker.value, target.value];
				} else {
					value = [this.timePicker.value, this.timePickerEnd.value];
				}
			} else {
				if (isInput(target)) {
					value = rangeStart
						? [target.value, this.value[1] || ""]
						: [this.value[0] || "", target.value];
				} else {
					value = [this.inputStart.value, this.inputEnd.value];
				}
			}
		}
		return value;
	}

	convertToISOString = (date, setToStartOfDay?: boolean) => {
		if (!date) {
			return;
		}
		const _date = new Date(date);
		if (setToStartOfDay) {
			_date.setHours(0, 0, 0, 0);
		}
		return _date.toISOString();
	};

	isDateOnly = (date) =>
		date.getHours() === 0 &&
		date.getMinutes() === 0 &&
		date.getSeconds() === 0 &&
		date.getMilliseconds() === 0;

	valueChanged = (value: string | [], rangeStart: boolean) => {
		if (!value) {
			return false;
		}

		const { range } = this;
		if (range) {
			if (!value.length) return true;
			if (this.value.length === 2) {
				if (rangeStart) {
					if (this.convertToISOString(value) === this.value[0]) {
						return false;
					}
				} else {
					if (this.convertToISOString(value) === this.value[1]) {
						return false;
					}
				}
			}
		} else {
			if (this.convertToISOString(value) === this.value) {
				return false;
			}
		}

		return true;
	};

	onValidate = (event) => {
		const { target } = event;
		const timeStart = target.classList.contains("hbr-time-start");
		const timeEnd = target.classList.contains("hbr-time-end");
		const rangeStart = target.classList.contains("hbr-range-start");
		const rangeEnd = target.classList.contains("hbr-range-end");
		const value = this.restructureValue(target, timeStart, rangeStart);

		let _value = value;
		if (timeStart) {
			_value = value[0];
		} else if (timeEnd) {
			_value = value[1];
		} else if (rangeStart) {
			_value = value[0];
		} else if (rangeEnd) {
			_value = value[1];
		}

		if (isEmpty(value)) {
			if (!this.range) {
				this.setInputValue("");
				if (this.time) this.setTimeValue("");
			} else {
				this.setInputValue([]);
				if (this.time) this.setTimeValue([]);
			}
			this.isValid = true;
			this.error = false;
			return true;
		}

		if (isValidDate(_value, this)) {
			if (typeof _value === "string" && _value?.trim() !== "") {
				if (!valueValidDate(_value)) {
					this.isValid = false;
					return;
				}

				if (!this.value && !_value) {
					return;
				}

				this.isValid = true;
				this.error = false;
				const formattedDate = formatInput(_value, this);
				if (!this.range) {
					this.setInputValue(formattedDate);
					if (!this.time) {
						this.dateString = new Date(this.input.value).toISOString();
					} else {
						this.setTimeValue(value);
						this.dateString = new Date(this.timePicker.value).toISOString();
					}
				} else {
					if (!this.time) {
						if (this._locale) {
							this.setInputValue([
								value[0]
									? Intl.DateTimeFormat(this._locale).format(new Date(value[0]))
									: "",
								value[1]
									? Intl.DateTimeFormat(this._locale).format(new Date(value[1]))
									: "",
							]);
						} else {
							this.setInputValue([
								value[0] ? formatInput(value[0], this) : "",
								value[1] ? formatInput(value[1], this) : "",
							]);
						}

						let start = new Date(this.inputStart.value);
						const localeNaturalFormat =
							!this._locale &&
							this.locale &&
							!this.locale.includes("en") &&
							!this.inputStart.value.includes("/");

						if (Number.isNaN(start.getTime())) {
							if (localeNaturalFormat) {
								const updatedFormat = swapDateFormat(this.inputStart.value);
								start = new Date(updatedFormat);
							} else {
								return true; //let users do the validation
							}
						}
						start.setHours(0, 0, 0, 0);

						let end = new Date(this.inputEnd.value);
						if (Number.isNaN(end.getTime())) {
							if (localeNaturalFormat) {
								const updatedFormat = swapDateFormat(this.inputEnd.value);
								end = new Date(updatedFormat);
							} else {
								return true; //let users do the validation
							}
						}
						end.setHours(0, 0, 0, 0);

						this.dateString = [
							this.inputStart.value ? start.toISOString() : "",
							this.inputEnd.value ? end.toISOString() : "",
						];
					} else {
						this.setTimeValue([
							value[0] ? value[0] : "",
							value[1] ? value[1] : "",
						]);
						this.dateString = [
							this.timePicker.value
								? new Date(this.timePicker.value).toISOString()
								: "",
							this.timePickerEnd.value
								? new Date(this.timePickerEnd.value).toISOString()
								: "",
						];
					}
				}
				if (this.value) this.value = this.dateString;
				return true;
			}
		} else {
			this.isValid = false;
			this.value = value;
			return false;
		}
	};

	newDateFn(date) {
		return new Date(date.getFullYear(), date.getMonth(), date.getDate());
	}

	async handleValidation(event) {
		const { type, target } = event;
		if (type === "hbr-change") event.stopPropagation();
		this.onValidating = true;
		const isValid = this.onValidate(event);

		if (isValid) {
			if (this.range) {
				const start = target.classList.contains("hbr-range-start");
				const end = target.classList.contains("hbr-range-end");
				if (start) {
					this.calendar.setStartRange(this.newDateFn(new Date(target.value)));
				} else if (end) {
					this.calendar.setEndRange(this.newDateFn(new Date(target.value)));
				}
				this.calendar.draw();
			} else {
				this.calendar.setDate(
					typeof this.value === "string"
						? new Date(this.value)
						: new Date(this.value[0]),
				);
			}
			this.error = false;
		} else {
			let empty: boolean;
			if (Array.isArray(this.value)) {
				empty = this.value.every((value) => !value || value === "");
			}
			if (empty) {
				this.error = false;
			} else {
				this.error = true;
			}
		}
		setTimeout(() => {
			this.onValidating = false;
		});
		if (typeof this.value === "string") {
			this.hbrChange.emit({
				isValid,
				value: this.value,
				focused: this.focusedInput,
				date: new Date(this.value),
				utc: new Date(this.value).toUTCString(),
			});
		} else if (Array.isArray(this.value)) {
			this.hbrChange.emit({
				isValid,
				value: this.value,
				focused: this.focusedInput,
				date:
					this.value?.length === 2
						? [new Date(this.value[0]), new Date(this.value[1])]
						: undefined,
				utc:
					this.value?.length === 2
						? [
								new Date(this.value[0]).toUTCString(),
								new Date(this.value[1]).toUTCString(),
						  ]
						: undefined,
			});
		}
	}

	handleTimePickerChange = (event) => {
		event.stopPropagation();
		const { target } = event;
		const timeValue = event.detail.value;
		const dateValue = this.dateString;
		if (!this.range) {
			if (timeValue && dateValue && !Array.isArray(dateValue)) {
				if (new Date(timeValue).getTime() !== new Date(dateValue).getTime()) {
					const updated = timeValue;
					this.value = updated;
					this.dateString = updated;
				}
			}
		} else {
			if (timeValue && dateValue && Array.isArray(dateValue)) {
				if (target.classList.contains("hbr-time-start")) {
					const updated = [timeValue, dateValue[1]];
					this.value = updated;
					this.dateString = updated;
				} else {
					const updated = [dateValue[0], timeValue];
					this.value = updated;
					this.dateString = updated;
				}
			}
		}
	};

	timePickerEl = (range, value) => {
		return (
			<Fragment>
				<hbr-time-picker
					class="hbr-time-start"
					ref={(ref) => {
						this.timePicker = ref;
					}}
					value={range ? (value.length ? value[0] : "") : value ? value : ""}
					size={this.size}
					exportparts="
						label: time-picker-label, base: time-picker-base, input-base: time-picker-input-base,
						prefix: time-picker-prefix, suffix: time-picker-suffix
					"
					popOver={false}
					onHbr-change={this.handleTimePickerChange}
				/>
				{range && (
					<hbr-time-picker
						class="hbr-time-end"
						ref={(ref) => {
							this.timePickerEnd = ref;
						}}
						value={value.length ? value[1] : ""}
						size={this.size}
						exportparts="
							label: time-picker-label, base: time-picker-base, input-base: time-picker-input-base,
							prefix: time-picker-prefix, suffix: time-picker-suffix
						"
						popOver={false}
						onHbr-change={this.handleTimePickerChange}
					/>
				)}
			</Fragment>
		);
	};

	startDateSuffix = () => {
		const { range, time, variant } = this;
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		if (this.trigger === "calendar") {
			return (
				<hbr-icon-button
					slot="suffix"
					asset={customSystemIcons?.["calendar-blank"] || calendarBlank}
					class="calendar-icon"
					aria={{
						label:
							this.aria?.calendarLabel ||
							this.ariaCalendar ||
							"Click to display calendar",
					}}
					data-testid="calendar-icon"
					onKeyDown={this.handleCalendarKeydown}
					ref={(el) => {
						this.calendarIconRef = el;
					}}
				/>
			);
		}
		if (!range && !time && this.trigger !== "calendar") {
			return <slot slot="suffix" name="suffix" />;
		}
		if (range && variant && variant === "outline") {
			return (
				<span slot="suffix" class="range--suffix-arrow-right-icon">
					<hbr-icon asset={customSystemIcons?.["arrow-right"] || arrowRight} />
				</span>
			);
		}
	};

	endDateSuffix = () => {
		const { variant } = this;
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return variant && variant === "outline" ? (
			<span slot="suffix" class="range--suffix-calendar-icon">
				<hbr-icon-button
					asset={customSystemIcons?.["calendar-blank"] || calendarBlank}
					class="calendar-icon"
					aria={{
						label: this.aria?.rangeCalendarLabel || "Click to show calendar",
					}}
				/>
			</span>
		) : !this.time ? (
			<slot slot="suffix-end" />
		) : (
			""
		);
	};

	getValueAsArray() {
		if (this.range && this.value === "") {
			return [];
		}
		return Array.isArray(this.value) ? this.value : [this.value];
	}

	getDateIdx = () => {
		const { format } = this;
		const formatArr = format.toLocaleLowerCase().split("/");
		let monthIdx: string | number;
		let dayIdx: string | number;
		let yearIdx: string | number;
		formatArr.forEach((value, i) => {
			const _value = value.toLocaleLowerCase();
			if (_value.includes("d")) dayIdx = i;
			else if (_value.includes("m")) monthIdx = i;
			else yearIdx = i;
		});
		return { monthIdx, dayIdx, yearIdx };
	};

	reConstructDate = (date) => {
		let newDate: Date | string;
		const { monthIdx, dayIdx, yearIdx } = this.getDateIdx();
		if (date && typeof date === "string") {
			//not until user input value exists. min/max date = 'object'
			const dateArr = date.split(/[.,\-/ ]/);
			newDate = `${dateArr[monthIdx]}/${dateArr[dayIdx]}/${dateArr[yearIdx]}`;
		}
		return newDate;
	};
	deConstructDate = (date) => {
		//putting back to original format when an error occurs
		if (typeof date !== "string") return date;
		if (Number.isNaN(Number(date[0]))) return date;
		const dateArr = date.split("/");
		if (dateArr.length !== 3) return date;
		const { monthIdx, dayIdx, yearIdx } = this.getDateIdx();
		const newArr: Array<string> = [];
		newArr[monthIdx] = dateArr[0];
		newArr[dayIdx] = dateArr[1];
		newArr[yearIdx] = dateArr[2];
		return newArr.join("/");
	};

	calendarEl = () => {
		const {
			role,
			label,
			modal,
			level,
			prevMonth,
			prevYear,
			nextMonth,
			nextYear,
		} = this.defaultAria;
		return (
			<slot name="calendar">
				<hbr-calendar
					ref={(el) => {
						this.calendar = el;
					}}
					exportparts="base:calendar-base, calendar, header, month-year, week-title, week, day"
					config={this.config}
					square={this.calendarStyle && this.calendarStyle === "square"}
					onHbr-day-click={this.handleDateChange}
					onHbr-day-keydown={this.handleDayKeydown}
					onHbr-title-keydown={this.handleCalendarTitleKeydown}
					onHbr-month-view={() => {
						this.calendarView = "month";
					}}
					onHbr-year-view={() => {
						this.calendarView = "year";
					}}
					onHbr-day-view={() => {
						this.calendarView = "day";
					}}
					style={
						this.calendarStyle && this.calendarStyle === "square"
							? {
									"--title-padding": "0px 4px 12px",
									"--range-first-title-padding": "10px 4px 12px 14px",
									"--range-last-title-padding": "10px 14px 12px 4px",
									"--title-title-justify-content": "center",
									"--title-title-width": "100px",
									"--title-text-padding-left": "0px",
									"--title-text-padding-right": "0px",
									"--title-gap": "var(--hbr-spacing-xs)",
									"--title-arrows-gap": "var(--hbr-spacing-xs)",
									"--title-year-icon-padding": "0px",
									"--thead-padding": "4px 4px 8px",
									"--th-line-height": "18px",
									"--dates-container-padding-top": "4px;",
									"--dates-container-padding-bottom": "4px;",
							  }
							: {}
					}
					aria={{
						role: this.aria?.calendarRole || role,
						label: this.aria?.calendarLabel || label,
						modal: this.aria?.calendarModal || modal,
						prevMonth: this.aria?.prevMonth || prevMonth,
						nextMonth: this.aria?.nextMonth || nextMonth,
						prevYear: this.aria?.prevYear || prevYear,
						nextYear: this.aria?.nextYear || nextYear,
						level: this.aria?.calendarLevel || level,
					}}
				/>
			</slot>
		);
	};

	timePanelEl = () => {
		return (
			<slot name="time">
				<hbr-time-panel
					exportparts="base:time-panel, panel-body:time-panel-body, panel-footer: time-panel-footer,
					column, column-header, column-menu, column-menu-base, column-menu-item, column-menu-item-text,
					wrapper:column-wrapper, checked-icon - The container that wraps the checked icon, nested, prefix: panel-prefix,
					label: panel-label, suffix: panel-suffix, check-mark, icon-checked, trigger-gap, trigger-gap-fixed"
					{...this.timeConfig}
					data-testid="time-panel"
					style={{
						"--host-width": "fit-content",
						"--column-menu-item-padding": "0px",
					}}
					ref={(ref) => {
						this.timePanelRef = ref;
					}}
					onHbr-menu-click={(event) => {
						event.preventDefault();
						event.stopPropagation();

						const { type } = event.detail;
						if (!this.timeConfig) this.timeConfig = {};
						this.timeConfig = {
							...this.timeConfig,
							[type]: event.detail.item.value,
						};
					}}
				/>
			</slot>
		);
	};

	panelEl = () => {
		return (
			<div
				part="panel"
				class={{
					"date-picker__panel": true,
					"date-picker__timePanel": this.timePanel,
				}}
			>
				{!this.timePanel ? (
					this.calendarEl()
				) : (
					<Fragment>
						<div part="panel-body" class="time-panel__panel-body">
							{this.calendarEl()}
							{this.timePanelEl()}
						</div>
						<div part="panel-footer" class="time-panel__panel-footer">
							<slot name="panel-footer">
								<hbr-button
									part="ok-button"
									size="small"
									onClick={this.handleOKButtonClick}
									disabled={!this.value && !this.calendarDaySelected}
									onKeyDown={this.handleOKButtonKeydown}
								>
									{this.timeConfig?.i18n?.ok || "OK"}
								</hbr-button>
							</slot>
						</div>
					</Fragment>
				)}
			</div>
		);
	};

	render() {
		const { name, placeholder, range, time, variant, magnetic, width, anchor } =
			this;
		const placeholderText = placeholder
			? placeholder
			: magnetic
			  ? this.format
			  : this.format.toLocaleLowerCase();

		if (this.anchor && !this.anchorRef.placeholder) {
			this.anchorRef.placeholder = placeholderText;
		}
		let startValue = "";
		let endValue = "";
		if (range) {
			const valueArr = this.getValueAsArray();
			if (valueArr.length) {
				startValue = valueArr[0];
				endValue = valueArr[1];
			}
		}

		const defaultWidth = width || "100%";
		const _width = {
			"--width": defaultWidth,
		};

		const outlined = this.variant && this.variant === "outline";
		let startWidth = _width;

		if (outlined) {
			let updatedWidth: string;
			if (width?.includes("px")) {
				updatedWidth = `${Number(width.replace(/\D/g, "")) - 2}px`;
				startWidth = {
					"--width": updatedWidth || "100%",
				};
			}
		}

		let hasError: boolean;
		let hasLabel: boolean;
		if (this.range && !this.outlined) {
			hasError =
				this.error &&
				Array.isArray(this.error) &&
				this.error.length &&
				this.error.some((item) => item === true);
			hasLabel = this.labelExist;
		} else {
			hasError = !!this.error;
			hasLabel = !!this.label;
		}

		const uniqueId = this.name || this.uuid;
		const dropdownProp: { hoist?: boolean } = {}; // Add type annotation for 'dropdownProp'
		if (this.hoist) dropdownProp.hoist = true; // Add 'hoist' property to 'dropdownProp' object

		let label = "";
		if (this.outlined) {
			label = "";
		} else {
			if (!this.range) {
				label = this.label;
			} else if (this.labelExist) {
				label = this.labels[0];
			}
		}

		let helpText: string;
		if (this.helpText && !this.range && !this.time) {
			helpText = this.helpText;
		}

		let showCustomHelpText: boolean;
		if (this.time || this.range) {
			showCustomHelpText = true;
		}

		let hasLabelSlot: boolean;
		let hasHelpTextSlot: boolean;
		if (!this.range) {
			hasLabelSlot = this.hasLabelSlot;
			if (!this.time) {
				hasHelpTextSlot = this.hasHelpTextSlot;
			}
		}

		let inputValue = "";
		if (!this.error) {
			if (range) {
				if (startValue) {
					if (this._locale) {
						inputValue = Intl.DateTimeFormat(this._locale).format(
							new Date(startValue),
						);
					} else {
						inputValue = formatInput(startValue, this);
					}
				} else {
					inputValue = "";
				}
				if (endValue) {
					if (this._locale) {
						endValue = Intl.DateTimeFormat(this._locale).format(
							new Date(endValue),
						);
					} else {
						endValue = formatInput(endValue, this);
					}
				}
			} else {
				if (this.value) {
					if (this._locale) {
						if (typeof this.value === "string") {
							inputValue = Intl.DateTimeFormat(this._locale).format(
								new Date(this.value),
							);
						}
					} else {
						inputValue = formatInput(this.value, this);
					}
				}
			}
		} else {
			/** Need to render formatted value for calendar selected dates (this.value === this.dateString) */
			if (this.range) {
				if (this.value?.length) {
					if (startValue && startValue === this.dateString[0]) {
						if (this._locale) {
							inputValue = Intl.DateTimeFormat(this._locale).format(
								new Date(startValue),
							);
						} else {
							inputValue = formatInput(startValue, this);
						}
					} else {
						inputValue = startValue;
					}
					if (endValue && endValue === this.dateString[1]) {
						if (this._locale) {
							endValue = Intl.DateTimeFormat(this._locale).format(
								new Date(endValue),
							);
						} else {
							endValue = formatInput(endValue, this);
						}
					}
				}
			} else {
				if (this.value) {
					if (this.value === this.dateString) {
						if (this._locale) {
							if (typeof this.value === "string") {
								inputValue = Intl.DateTimeFormat(this._locale).format(
									new Date(this.value),
								);
							}
						} else {
							inputValue = formatInput(this.value, this);
						}
					} else if (typeof this.value === "string") {
						inputValue = this.value;
					}
				}
			}
		}

		if (anchor) {
			let anchorRef: HTMLElement | HTMLHbrInputElement;
			if (typeof anchor === "string") {
				anchorRef = document.querySelector(anchor);
			} else {
				anchorRef = anchor;
			}
			if (!range) {
				if (anchorRef.tagName === "HBR-INPUT") {
					(anchorRef as HTMLHbrInputElement).value = inputValue;
				}
			}
		}

		return (
			<Host>
				{range && outlined && (hasLabel || this.hasLabelSlot) && (
					<div
						part="label"
						id={`date-picker-label-${uniqueId}`}
						class={`
							form-control__label range-picker--outline-label
							range-picker--outline_label--${this.size}
							${hasError ? " error" : ""}
							${this.disabled ? " disabled" : ""}
							`}
					>
						<slot name="label">{this.label}</slot>{" "}
						{this.required && (
							<span part="asterisk" class="form-control-asterisk-required">
								*
							</span>
						)}
						<slot name="label-suffix" />
					</div>
				)}
				<div
					part={`base${range ? " range" : ""}`}
					class={{
						"date-picker--popover": true,
						"date-picker--disabled": this.disabled,
						"range-picker": this.range,
						"time-picker": this.time,
						"time-panel": this.timePanel,
						"range-picker--outline": variant && variant === "outline",
						"range-picker--focused": this.hasFocus,
						"date-picker--error": !!(this.error || hasError),
						"date-picker--has-label": hasLabel,
						"date-picker--has-help-text": this.hasHelpText,
						"date-picker--has-front": this.hasFrontSlot,
						"date-picker--has-rear": this.hasRearSlot,
						// Sizes
						"date-picker--small": this.size === "small",
						"date-picker--medium": this.size === "medium",
						"date-picker--large": this.size === "large",
						[`${this.calendarView}-view`]: true, //since date picker is not re-rendering, this is not working
					}}
					ref={(ref) => {
						this.datePicker = ref;
					}}
					id={`date-picker-${uniqueId}`}
				>
					<hbr-dropdown
						exportparts="base:dropdown, trigger, panel:dropdown-panel"
						id="date-picker-dropdown"
						panelFitTrigger={true}
						closeOnSelect={false}
						uncontrolled
						ref={(el) => {
							this.dropdown = el;
						}}
						open={this.open}
						disabled={this.disabled}
						class="date-picker--dropdown"
						distance={outlined ? 4 : 2}
						anchor={this.anchor as string | HTMLElement}
						placement={this.placement}
						{...dropdownProp}
					>
						{!this.anchor ? (
							<Fragment>
								<hbr-input
									class={{
										"hbr-range-start": this.range,
									}}
									exportparts="label, element, base: input-base, input, help-text, prefix, suffix"
									ref={(ref) => {
										if (this.range) {
											this.inputStart = ref;
										} else {
											this.input = ref;
										}
									}}
									name={`${name ? `${name}-` : ""}date-${this.uuid}${
										range ? "-start" : ""
									}`}
									slot="trigger"
									label={label}
									placeholder={
										this.placeholdersExist
											? this.placeholder[0]
												? this.placeholder[0]
												: ""
											: placeholderText
									}
									error={this.errorExist ? this.error[0] : this.error}
									required={this.required}
									size={this.size}
									disabled={this.disabled}
									help-text={helpText}
									onHbr-input={this.handleInput}
									onKeyDown={this.handleKeydown}
									onKeyUp={this.handleKeyup}
									onHbr-focus={this.handleFocus}
									onHbr-blur={this.handleFocusout}
									onHbr-change={
										this.range
											? this.handleInputStartChange
											: this.handleHbrChange
									}
									onClick={this.handleClick}
									style={startWidth}
									aria={{ label: this.aria?.inputLabel || this.ariaInput }}
									value={inputValue}
									data-testid="date-picker-input"
								>
									{this.startDateSuffix()}
									{hasLabelSlot && <slot name="label" slot="label" />}
									{this.hasStartLabelSlot && (
										<slot name="start-label" slot="label" />
									)}
									{hasHelpTextSlot && (
										<slot name="help-text" slot="help-text" />
									)}
									<slot name="clear-icon" slot="clear-icon" />
									{this.hasFrontSlot && <slot name="front" slot="front" />}
									{this.hasRearSlot && <slot name="rear" slot="rear" />}
								</hbr-input>
								{range && (
									<hbr-input
										class={{
											"hbr-range-end": this.range,
										}}
										exportparts="
											base:base-end,
											input:input-end,
											label:label-end,
											prefix:prefix-end,
											clear-button:clear-button-end,
											password-toggle-button:password-toggle-button-end,
											suffix:suffix-end
										"
										ref={(ref) => {
											this.inputEnd = ref;
										}}
										name={`${name ? `${name}-` : ""}date-${this.uuid}-end`}
										slot="trigger"
										label={
											!outlined ? (this.labelExist ? this.labels[1] : "") : ""
										}
										placeholder={
											this.placeholdersExist
												? this.placeholder[1]
												: magnetic
												  ? this.format
												  : this.format.toLocaleLowerCase()
										}
										error={this.errorExist ? this.error[1] : false}
										required={this.required}
										size={this.size}
										disabled={this.disabled}
										onHbr-input={this.handleInput}
										onKeyDown={this.handleKeydown}
										onKeyUp={this.handleKeyup}
										onHbr-focus={this.handleFocus}
										onHbr-blur={this.handleFocusout}
										onHbr-change={this.handleInputEndChange}
										onClick={this.handleClick}
										value={endValue}
										style={_width}
										data-testid="date-picker-input-end"
									>
										{this.hasEndLabelSlot && (
											<slot name="end-label" slot="label" />
										)}
										<slot slot="prefix-end" name="prefix-end" />
										{this.endDateSuffix()}
									</hbr-input>
								)}
							</Fragment>
						) : null}

						{this.panelEl()}
					</hbr-dropdown>
					{time && this.timePickerEl(range, this.value)}
					{showCustomHelpText && (
						<div class={"date-picker__help-text"} part="help-text">
							<slot name="help-text">{this.helpText}</slot>
						</div>
					)}
				</div>
			</Host>
		);
	}
}
