import { CalendarConfig } from "../calendar/types";

const NUMERIC_DATE_PARTS = {
	year: "numeric",
	month: "numeric",
	day: "numeric",
} satisfies Intl.DateTimeFormatOptions;

const PADDED_NUMERIC_DATE_PARTS = {
	year: "numeric",
	month: "2-digit",
	day: "2-digit",
} satisfies Intl.DateTimeFormatOptions;

const ENGLISH_FORMAT_OPTIONS = {
	year: "numeric",
	month: "short",
	day: "numeric",
} satisfies Intl.DateTimeFormatOptions;

const LONG_DATE_OPTIONS = {
	year: "numeric",
	month: "long",
	day: "numeric",
} satisfies Intl.DateTimeFormatOptions;

const DEFAULT_EN_I18N = {
	previousMonth: "Previous Month",
	nextMonth: "Next Month",
	months: [
		"January",
		"February",
		"March",
		"April",
		"May",
		"June",
		"July",
		"August",
		"September",
		"October",
		"November",
		"December",
	],
	weekdays: [
		"Sunday",
		"Monday",
		"Tuesday",
		"Wednesday",
		"Thursday",
		"Friday",
		"Saturday",
	],
	weekdaysShort: ["S", "M", "T", "W", "T", "F", "S"],
};

const createDateFromParts = (
	year: number,
	month: number,
	day: number,
): Date | null => {
	if (
		!Number.isInteger(year) ||
		!Number.isInteger(month) ||
		!Number.isInteger(day)
	) {
		return null;
	}

	const parsed = new Date(year, month - 1, day);
	if (
		parsed.getFullYear() !== year ||
		parsed.getMonth() !== month - 1 ||
		parsed.getDate() !== day
	) {
		return null;
	}

	return parsed;
};

const parseDate = (value: string | number | Date): Date | null => {
	if (value instanceof Date) {
		return Number.isNaN(value.getTime()) ? null : new Date(value);
	}

	const parsed = new Date(value);
	return Number.isNaN(parsed.getTime()) ? null : parsed;
};

const formatDate = (
	value: string | number | Date,
	locale: string,
	options: Intl.DateTimeFormatOptions,
) => {
	const parsed = parseDate(value);
	return parsed ? new Intl.DateTimeFormat(locale, options).format(parsed) : "";
};

const getDatePartsOrder = (
	locale: string,
	options: Intl.DateTimeFormatOptions = NUMERIC_DATE_PARTS,
) =>
	new Intl.DateTimeFormat(locale, options)
		.formatToParts(new Date(2001, 10, 22))
		.filter((part) => ["year", "month", "day", "literal"].includes(part.type));

const parseNumericDateString = (
	dateString: string,
	order: Array<"year" | "month" | "day">,
): Date | null => {
	const values = dateString.match(/\d+/g);
	if (!values || values.length < 3) {
		return null;
	}

	const parts = { year: 0, month: 0, day: 0 };
	order.forEach((part, index) => {
		parts[part] = Number(values[index]);
	});

	return createDateFromParts(parts.year, parts.month, parts.day);
};

const getLocaleDateMetadata = (
	locale: string,
	options: Intl.DateTimeFormatOptions = NUMERIC_DATE_PARTS,
) => {
	const parts = getDatePartsOrder(locale, options);

	return {
		parts,
		order: parts
			.filter((part) => part.type !== "literal")
			.map((part) => part.type as "year" | "month" | "day"),
	};
};

const getLocaleMonths = (
	locale: string,
	format: "long" | "short" | "narrow" = "long",
) =>
	Array.from({ length: 12 }, (_, month) =>
		new Intl.DateTimeFormat(locale, { month: format }).format(
			new Date(2020, month, 1),
		),
	);

const getLocaleWeekdays = (
	locale: string,
	format: "long" | "short" | "narrow" = "long",
) =>
	Array.from({ length: 7 }, (_, offset) =>
		new Intl.DateTimeFormat(locale, { weekday: format }).format(
			new Date(2020, 5, 7 + offset),
		),
	);

const getFormatPattern = (locale: string) =>
	getDatePartsOrder(locale, PADDED_NUMERIC_DATE_PARTS)
		.map((part) => {
			switch (part.type) {
				case "year":
					return "YYYY";
				case "month":
					return "MM";
				case "day":
					return "DD";
				default:
					return part.value;
			}
		})
		.join("");

const getFirstDayOfWeek = (locale: string) => {
	try {
		const intlLocale = new Intl.Locale(locale) as Intl.Locale & {
			weekInfo?: { firstDay?: number };
		};
		if (intlLocale.weekInfo?.firstDay) {
			return intlLocale.weekInfo.firstDay % 7;
		}
	} catch {
		// Fallback below.
	}

	return 0;
};

const getLocalizedDateConfig = (locale: string) => ({
	months: getLocaleMonths(locale, "long"),
	monthsShort: getLocaleMonths(locale, "short"),
	weekdays: getLocaleWeekdays(locale, "long"),
	weekdaysShort: getLocaleWeekdays(locale, "short"),
});

export const isEmpty = (value) =>
	value === null ||
	value === "null" ||
	value === undefined ||
	value === "undefined" ||
	value === "";

export function valueValidDate(str) {
	return Boolean(parseDate(str));
}

export function isValidDate(str, self) {
	const { minDate: min, maxDate: max } = self;
	if (!valueValidDate(str)) return;
	if (!min && !max) return true;
	if (min) {
		if (!valueValidDate(min)) return;
		if (new Date(str).getTime() < new Date(min).getTime()) {
			return false;
		}
	}
	if (max && !valueValidDate(max)) return;
	return true;
}

export function validUserInput(date: string) {
	if (Number.isNaN(Number(date[0]))) return true; /** skip if neutral format */
	const numericDate = parseNumericDateString(
		date,
		/^\d{4}\D/.test(date) ? ["year", "month", "day"] : ["month", "day", "year"],
	);
	return Boolean(numericDate);
}

/**
 * Handles non-English "MMM D, YYYY" formats (as generated in #517)
 * by converting Intl.DateTimeFormat(locale).format(date) (in line #515) output into a format suitable for validation.
 */
export function swapDateFormat(date: string) {
	if (Number.isNaN(Number(date[0]))) return ""; /** skip if neutral format */

	// Replace any non-numeric character (except "-" or "/") with "/"
	let cleaned = date.replace(/[^0-9/-]+/g, "/");
	if (Number.isNaN(Number(cleaned[cleaned.length - 1]))) {
		cleaned = cleaned.slice(0, cleaned.length - 1);
	}

	// Check if the cleaned string contains only valid separators
	if (/^[\d/-]+$/.test(cleaned)) {
		return cleaned;
	}

	// Fallback: return the cleaned string
	return cleaned;
}

/** usage: parseLocaleDate("2025/4/18", "ja-JP") -> Wed Apr 18 2025 00:00:00 GMT-0700 (Pacific Daylight Time) */
export function parseLocaleDate(
	dateString: string,
	locale: string,
	formatOptions?: Intl.DateTimeFormatOptions,
): Date | null {
	try {
		const { order } = getLocaleDateMetadata(
			locale,
			formatOptions || NUMERIC_DATE_PARTS,
		);
		return parseNumericDateString(dateString, order);
	} catch (error) {
		console.error("Error parsing locale date:", error);
		return null;
	}
}
/** Usage: parseToEnUsFormat("2025/4/18", "ja-JP")
 * converts a date from the "ja-JP" format ("2025/4/18") to the "en-US" format ("4/18/2025")
 * for validUserInput validation. */
export function parseToEnUsFormat(
	date: string,
	locale: string,
	formatOptions?: Intl.DateTimeFormatOptions,
): Date | null | string {
	const parsed: Date = parseLocaleDate(date, locale, formatOptions);
	if (parsed) {
		return Intl.DateTimeFormat("en-US").format(parsed);
	}
	return null;
}

export function getMinDate(minDate: string | number | Date): Date {
	if (minDate !== undefined) {
		if (minDate === 0 || parseDate(minDate)) {
			return new Date(minDate);
		}
	}
	return null;
}

export function getMaxDate(maxDate: string | Date) {
	if (maxDate !== undefined) {
		if (parseDate(maxDate)) {
			return new Date(maxDate);
		}
	}
	return null;
}

export function momentDay(event) {
	return parseDate(event?.target?.value);
}

export function formatInput(value, self?) {
	const { locale } = self;
	if (!isValidDate(value, self)) {
		return value;
	}
	let formattedDate: string;
	switch (locale.toLocaleLowerCase()) {
		case "ko":
			formattedDate = formatDate(value, "ko", LONG_DATE_OPTIONS);
			break;
		case "ja":
			formattedDate = formatDate(value, "ja", LONG_DATE_OPTIONS);
			break;
		case "zh":
		case "zh-cn":
			formattedDate = formatDate(value, "zh-CN", LONG_DATE_OPTIONS);
			break;
		default: {
			let _value = value;
			if (self.customFormat) {
				_value = self.reConstructDate(value);
			}
			formattedDate = formatDate(_value, "en-US", ENGLISH_FORMAT_OPTIONS);
		}
	}
	return formattedDate;
}

export function getDateFormat(self) {
	const { locale, format, firstDay, i18n } = self;
	const applyLocaleDateConfig = (displayLocale: string) => {
		if (!format) {
			self.format = getFormatPattern(displayLocale);
		}
		const _i18n = getLocalizedDateConfig(displayLocale);
		if (self.i18n) {
			for (const prop in self.i18n) {
				if (_i18n[prop]) {
					_i18n[prop] = self.i18n[prop];
				} else {
					self.i18n[prop] = _i18n[prop];
				}
			}
		} else {
			self.i18n = _i18n;
		}

		if (!firstDay) {
			self.firstDay = getFirstDayOfWeek(displayLocale);
		}
	};

	switch (locale.toLocaleLowerCase()) {
		case "ko":
			applyLocaleDateConfig("ko");
			break;
		case "ja":
			applyLocaleDateConfig("ja");
			break;
		case "zh":
		case "zh-cn":
			applyLocaleDateConfig("zh-CN");
			break;
		default:
			if (locale && !locale.toLowerCase().includes("en")) {
				return;
			}
			if (!format) {
				self.format = "MM/DD/YYYY";
			}
			if (!i18n) {
				self.i18n = { ...DEFAULT_EN_I18N };
			}
			if (!firstDay) {
				self.firstDay = 0;
			}
	}
}

export function getEnFormat(self) {
	if (!self.format) {
		self.format = "MM/DD/YYYY";
	}
	const _i18n = { ...DEFAULT_EN_I18N };
	if (self.i18n) {
		for (const prop in self.i18n) {
			if (_i18n[prop]) {
				_i18n[prop] = self.i18n[prop];
			}
		}
	}
	self.i18n = _i18n;

	if (!self.firstDay) {
		self.firstDay = 0;
	}
}

export const setDateInFormat: (date: string | Date) => Date = (date) => {
	if (!(date instanceof Date) || !Number.isNaN(date.getTime())) {
		const newDate = new Date(date);
		newDate.setHours(0, 0, 0, 0);
		return newDate;
	}
	return date;
};

const onSelectFn = (self, date) => {
	const { calendar, time, locale, _locale } = self;
	self.error = false;
	self.onSelectFromCalendar = true;

	let startDate = time ? self.timePicker.value : self.inputStart.value;
	let endDate = time ? self.timePickerEnd.value : self.inputEnd.value;

	if (
		!_locale &&
		locale &&
		!locale.includes("en") &&
		!startDate.includes("/")
	) {
		/** Change from 2025년 5월 15일 to 2025/5/15 */
		startDate = swapDateFormat(startDate);
		endDate = swapDateFormat(endDate);
	}

	calendar.draw();
	if (startDate && endDate) {
		self.dateString = [
			new Date(startDate).toISOString(),
			new Date(endDate).toISOString(),
		];
	} else if (startDate) {
		self.dateString = [new Date(startDate).toISOString(), ""];
	} else {
		self.dateString = ["", new Date(date).toISOString()];
	}
	if (!self.timePanel) {
		if (self.value === self.dateString) {
			return;
		}
		self.value = self.dateString;
	} else {
		self.calendarDaySelected = true;
	}

	self.hbrChange.emit({
		isValid: self.isValid,
		value: self.dateString,
		focused: self.focusedInput,
		date: self.dateString?.length === 2 ? [startDate, endDate] : undefined,
		utc:
			self.dateString?.length === 2
				? [new Date(startDate).toUTCString(), new Date(endDate).toUTCString()]
				: undefined,
	});
	self.isValid = true;
};

export const initConfig = (self) => {
	const { i18n, firstDay, format, showMonthAfterYear, _locale } = self;
	let isYearBeforeMonth: boolean;
	if (!format) {
		const langCode =
			_locale || navigator.language || document.documentElement.lang;
		const formatter = new Intl.DateTimeFormat(langCode);
		const showFormat = formatter.format();
		const firstFourDigit = showFormat.slice(0, 4);

		if (typeof Number(firstFourDigit) === "number") {
			isYearBeforeMonth = true;
		}
	}
	let config: CalendarConfig = {
		minDate: getMinDate(self.minDate),
		maxDate: getMaxDate(self.maxDate),
		numberOfMonths: self.range ? 2 : 1, //we can add numberOfMonths prop if needed in the future
		i18n,
		firstDay,
		showMonthAfterYear: !showMonthAfterYear
			? format
				? format[0].toLocaleLowerCase() === "y"
				: isYearBeforeMonth
			: showMonthAfterYear,
		keyboardInput: false,
		yearRange: self.yearRange,
	};
	if (self.showDaysInNextAndPreviousMonths) {
		config.showDaysInNextAndPreviousMonths =
			self.showDaysInNextAndPreviousMonths;
	}
	if (self.calendarStyle) {
		config.calendarStyle = self.calendarStyle;
	}
	if (self.range) {
		if (self.inputStart?.value) {
			config.startRange = setDateInFormat(self.inputStart.value) as Date;
		} else if (self.value) {
			config.startRange = setDateInFormat(self.value[0]) as Date;
		}
		if (self.inputEnd?.value) {
			config.endRange = setDateInFormat(self.inputEnd.value) as Date;
		} else if (self.value) {
			config.endRange = setDateInFormat(self.value[1]) as Date;
		}

		config = {
			...config,
			mainCalendar: self.mainCalendar || "left",
			onSelect: (date: Date) => onSelectFn(self, date),
		};
	} else {
		if (!self.error && self.value) {
			config.defaultDate = setDateInFormat(self.value) as Date;
			config.setDefaultDate = true;
		}
		config.onSelect = (date: Date, calendar?: true) => {
			self.error = false;
			if (calendar) {
				self.onSelectFromCalendar = true;
			}
			const timepicker = self.time;

			if (timepicker && !self.error) {
				const timeValue = self.value;
				if (timeValue) {
					date.setHours(new Date(timeValue).getHours());
					date.setMinutes(new Date(timeValue).getMinutes());
					date.setSeconds(new Date(timeValue).getSeconds());
				}
			}
			self.dateString = date.toISOString();
			if (!self.timePanel) {
				if (self.value === self.dateString) {
					return;
				}
				self.value = self.dateString;
			}

			if (!self.timePanel) {
				if (self._locale) {
					/** make sure to render in locale format */
					self.input.value = Intl.DateTimeFormat(self._locale).format(date);
				} else {
					self.input.value = formatDate(date, "en-US", ENGLISH_FORMAT_OPTIONS);
				}
			} else {
				self.calendarDaySelected = true;
			}
			if (timepicker) self.timePicker.value = new Date(date);
			self.isValid = true;
			if (!self.timePanel) {
				self.hbrChange.emit({
					isValid: self.isValid,
					value: self.dateString, //returns ISOString
					focused: self.focusedInput,
					utc: date.toUTCString(), // returns UTCString
					date: date, // returns date in Date object
				});
			}
		};
	}
	return config;
};
